from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum


class CheckKind(Enum):
    """The kinds of checks that are run for each package change."""

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """The possible outcomes of a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


@dataclass
class CheckResult:
    """The result of a single check."""

    status: CheckStatus
    details: str


@dataclass
class PackageChange:
    """A single package version change detected in a diff."""

    name: str
    old_version: str | None
    new_version: str
    checks: dict[CheckKind, CheckResult] = field(default_factory=dict)
    repo_url: str | None = None

    @property
    def needs_agent(self) -> bool:
        """Return True if at least one check needs an agent."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT for result in self.checks.values()
        )


# Precedence used when aggregating a check kind's status across all packages.
# A more "attention worthy" status wins over a less worthy one.
_STATUS_PRECEDENCE = {
    CheckStatus.NEEDS_AGENT: 3,
    CheckStatus.FAIL: 2,
    CheckStatus.WARN: 1,
    CheckStatus.PASS: 0,
}


@dataclass
class CheckRunResult:
    """The result of running all checks for a PR."""

    pr_number: int
    packages: list[PackageChange] = field(default_factory=list)

    @property
    def needs_agent(self) -> bool:
        """Return True if any package needs an agent."""
        return any(package.needs_agent for package in self.packages)

    def _aggregate(self, kind: CheckKind) -> str:
        """Aggregate a single check kind's status across all packages."""
        best: CheckStatus | None = None
        for package in self.packages:
            result = package.checks.get(kind)
            if result is None:
                continue
            if best is None or (
                _STATUS_PRECEDENCE[result.status] > _STATUS_PRECEDENCE[best]
            ):
                best = result.status
        if best is None:
            return "skipped"
        return best.value

    def to_dict(self) -> dict:
        """Return a JSON-serializable representation of the run result."""
        # Imported lazily to avoid a circular import (render imports models).
        from .render import render_comment

        aggregates = {kind.value: self._aggregate(kind) for kind in CheckKind}

        result: dict = {
            "pr_number": self.pr_number,
            "needs_agent": self.needs_agent,
            "rendered_comment": render_comment(self),
            "packages": [_package_to_dict(package) for package in self.packages],
            "checks": aggregates,
        }
        # Expose each check kind at the top level too (e.g. "repo_public").
        result.update(aggregates)
        return result


def _package_to_dict(package: PackageChange) -> dict:
    """Return a JSON-serializable representation of a package change."""
    return {
        "name": package.name,
        "old_version": package.old_version,
        "new_version": package.new_version,
        "repo_url": package.repo_url,
        "needs_agent": package.needs_agent,
        "checks": {
            kind.value: {"status": result.status.value, "details": result.details}
            for kind, result in package.checks.items()
        },
    }
