from __future__ import annotations

from fnmatch import fnmatch
import re

from .models import PackageChange

# A pinned requirement line: ``name[extras]==version``. Environment markers and
# inline comments are stripped before this is applied.
_REQ_RE = re.compile(
    r"^(?P<name>[A-Za-z0-9][A-Za-z0-9._-]*)\s*"
    r"(?:\[[^\]]*\])?\s*"
    r"==\s*(?P<version>[^\s]+)"
)


def _canonical_name(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _is_tracked_file(path: str) -> bool:
    """Return True if the given diff path refers to a tracked requirements file."""
    # Strip a trailing tab-separated timestamp used by some diff producers.
    path = path.split("\t", 1)[0].strip()
    if not path or path == "/dev/null":
        return False
    # Drop a leading a/ or b/ prefix added by git.
    basename = path.split("/")[-1]
    return fnmatch(basename, "requirements*.txt")


def _parse_requirement(content: str) -> tuple[str, str] | None:
    """Parse a requirement line into a (canonical_name, version) tuple."""
    # Strip inline comments (e.g. "foo==1.0  # old").
    content = content.split("#", 1)[0]
    # Strip environment markers (e.g. "foo==1.0 ; python_version < '3.9'").
    content = content.split(";", 1)[0].strip()
    if not content:
        return None
    match = _REQ_RE.match(content)
    if not match:
        return None
    return _canonical_name(match.group("name")), match.group("version").strip()


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff and return the package version changes it contains."""
    changes: list[PackageChange] = []
    seen: set[str] = set()

    tracked = False
    removed: dict[str, str] = {}
    added: dict[str, str] = {}

    def flush() -> None:
        """Emit changes accumulated for the current file."""
        for name, new_version in added.items():
            if name in seen:
                continue
            old_version = removed.get(name)
            if old_version == new_version:
                # No actual version change for this package.
                continue
            seen.add(name)
            changes.append(
                PackageChange(
                    name=name,
                    old_version=old_version,
                    new_version=new_version,
                )
            )

    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            # New file target: flush the previous file and reset state.
            flush()
            removed = {}
            added = {}
            tracked = _is_tracked_file(line[4:])
            continue
        if (
            line.startswith("--- ")
            or line.startswith("diff ")
            or line.startswith("index ")
            or line.startswith("@@")
            or line.startswith("new file")
            or line.startswith("deleted file")
            or line.startswith("rename ")
            or line.startswith("similarity ")
            or line.startswith("\\")
        ):
            continue
        if not tracked:
            continue
        if line.startswith("+"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                added[parsed[0]] = parsed[1]
        elif line.startswith("-"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                removed[parsed[0]] = parsed[1]

    flush()
    return changes
