from __future__ import annotations

from dataclasses import dataclass
from urllib.parse import urlparse

import requests

_BASE = "https://pypi.org"
_TIMEOUT = 30

# Hostnames considered known code hosts. Matched exactly to reject lookalikes
# such as "github.com.evil.com".
_KNOWN_CODE_HOSTS = frozenset(
    {"github.com", "gitlab.com", "www.github.com", "www.gitlab.com"}
)

# project_urls keys that are preferred as the source repository.
_PREFERRED_KEYS = ("Source", "Repository")


@dataclass
class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    project_urls: dict
    repo_url: str | None
    file_provenance_urls: list[str]
    found: bool


@dataclass
class ProvenanceResult:
    """The result of a provenance/attestation check."""

    has_attestation: bool
    publisher_kind: str | None
    recognized_publisher: bool
    detail: str


def _strip_control(value: str) -> str:
    """Remove backtick and newline characters from a value."""
    return value.replace("`", "").replace("\r", "").replace("\n", "")


def _get(url: str) -> tuple[requests.Response | None, int | None]:
    """Perform a GET request, returning (response, status) or (None, None)."""
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return None, None
    return response, response.status_code


def _json(response: requests.Response) -> dict | None:
    """Return parsed JSON or None when the body is not valid JSON."""
    try:
        data = response.json()
    except ValueError:
        return None
    if not isinstance(data, dict):
        return None
    return data


def _is_known_code_host(url: str) -> bool:
    """Return True if the URL's hostname is exactly a known code host."""
    if not isinstance(url, str) or not url:
        return False
    try:
        hostname = urlparse(url).hostname
    except ValueError:
        return False
    return hostname is not None and hostname.lower() in _KNOWN_CODE_HOSTS


def _select_repo_url(project_urls: dict) -> str | None:
    """Select a source repository URL from the project_urls mapping."""
    if not isinstance(project_urls, dict):
        return None
    # Prefer the canonical keys, but only when they point to a known code host.
    for key in _PREFERRED_KEYS:
        value = project_urls.get(key)
        if _is_known_code_host(value):
            return value
    # Otherwise, scan all values for a known code host URL.
    for value in project_urls.values():
        if _is_known_code_host(value):
            return value
    return None


def _build_info(name: str, version: str, data: dict, found: bool) -> PypiPackageInfo:
    """Build a PypiPackageInfo from a PyPI JSON response body."""
    info = data.get("info") or {}
    project_urls = info.get("project_urls") or {}
    if not isinstance(project_urls, dict):
        project_urls = {}

    repo_url = _select_repo_url(project_urls)
    if repo_url is not None:
        repo_url = _strip_control(repo_url)

    file_provenance_urls: list[str] = []
    urls = data.get("urls") or []
    if urls:
        # Use only the first file, ignoring any urls[].provenance field.
        filename = urls[0].get("filename")
        if filename:
            file_provenance_urls = [
                f"{_BASE}/integrity/{name}/{version}/{filename}/provenance"
            ]

    return PypiPackageInfo(
        project_urls=project_urls,
        repo_url=repo_url,
        file_provenance_urls=file_provenance_urls,
        found=found,
    )


def _empty_info() -> PypiPackageInfo:
    """Return the info returned when the package cannot be fetched at all."""
    return PypiPackageInfo(
        project_urls={}, repo_url=None, file_provenance_urls=[], found=False
    )


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata from PyPI for a specific version."""
    response, status = _get(f"{_BASE}/pypi/{name}/{version}/json")
    if response is None:
        # Network error on the versioned endpoint.
        return _empty_info()

    if status == 404:
        # Fall back to the latest-release endpoint.
        latest, latest_status = _get(f"{_BASE}/pypi/{name}/json")
        if latest is None or latest_status != 200:
            return _empty_info()
        data = _json(latest)
        if data is None:
            return _empty_info()
        info = _build_info(name, version, data, found=False)
        info.file_provenance_urls = []
        return info

    if status != 200:
        # 5xx and other unexpected statuses.
        return _empty_info()

    data = _json(response)
    if data is None:
        return _empty_info()
    return _build_info(name, version, data, found=True)


def _parse_bundles(data: dict) -> ProvenanceResult | None:
    """Parse attestation bundles, returning a result if a kind is found."""
    bundles = data.get("attestation_bundles") or []
    for bundle in bundles:
        if not isinstance(bundle, dict):
            continue
        publisher = bundle.get("publisher") or {}
        if not isinstance(publisher, dict):
            continue
        kind = publisher.get("kind")
        if kind is None:
            # Entries without a kind field are skipped.
            continue
        kind = _strip_control(str(kind))
        recognized = kind == "GitHub"
        if recognized:
            detail = f"PEP 740 provenance attestation present from recognised publisher: {kind}."
        else:
            detail = (
                "PEP 740 provenance attestation present from unrecognised "
                f"publisher: {kind}."
            )
        return ProvenanceResult(
            has_attestation=True,
            publisher_kind=kind,
            recognized_publisher=recognized,
            detail=detail,
        )
    return None


def check_provenance(pkg: PypiPackageInfo) -> ProvenanceResult:
    """Check PEP 740 provenance attestations for a package."""
    if not pkg.found:
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="Package version not found on PyPI; cannot verify provenance.",
        )

    for url in pkg.file_provenance_urls:
        response, status = _get(url)
        if response is None:
            # Network error; try the next URL.
            continue
        if status == 404:
            continue
        if status != 200:
            continue
        data = _json(response)
        if data is None:
            continue
        result = _parse_bundles(data)
        if result is not None:
            return result
        # A response was returned but no usable publisher kind was found.
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="Provenance attestation present but publisher could not be parsed.",
        )

    return ProvenanceResult(
        has_attestation=False,
        publisher_kind=None,
        recognized_publisher=False,
        detail="No PEP 740 provenance attestation present",
    )
