from __future__ import annotations

from .models import CheckKind, CheckResult, CheckRunResult, CheckStatus, PackageChange

MARKER = "<!-- requirements-check -->"

_STATUS_EMOJI = {
    CheckStatus.PASS: "✅",
    CheckStatus.WARN: "⚠️",
    CheckStatus.FAIL: "❌",
    CheckStatus.NEEDS_AGENT: "🔎",
}

# The order in which check kinds are displayed.
_KIND_ORDER = list(CheckKind)


def _version_label(package: PackageChange) -> str:
    """Return a human readable version transition label."""
    if package.old_version is None:
        return f"{package.name} (new → {package.new_version})"
    return f"{package.name} ({package.old_version} → {package.new_version})"


def _cell(package: PackageChange, kind: CheckKind) -> str:
    """Return the table cell content for a package/kind."""
    result = package.checks.get(kind)
    if result is None:
        return "—"
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"{{{{CHECK_CELL:{package.name}:{kind.value}}}}}"
    return _STATUS_EMOJI[result.status]


def _detail_line(package: PackageChange, kind: CheckKind) -> str:
    """Return the detail bullet for a package/kind."""
    result = package.checks.get(kind)
    if result is None:
        return f"- **{kind.value}**: — skipped."
    if result.status is CheckStatus.NEEDS_AGENT:
        return f"- **{kind.value}**: {{{{CHECK_DETAIL:{package.name}:{kind.value}}}}}"
    return f"- **{kind.value}**: {_STATUS_EMOJI[result.status]} {result.details}"


def _all_pass(result: CheckRunResult) -> bool:
    """Return True if every present check in every package passed."""
    if not result.packages:
        return False
    for package in result.packages:
        for check in package.checks.values():
            if check.status is not CheckStatus.PASS:
                return False
    return True


def render_comment(result: CheckRunResult) -> str:
    """Render a Markdown comment summarizing the check run."""
    lines: list[str] = [MARKER, "", "## Requirements supply-chain check", ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        lines.append("")
        return "\n".join(lines)

    all_pass = _all_pass(result)
    needs_agent = result.needs_agent

    if all_pass:
        lines.append("All requirements checks passed. ✅")
    elif needs_agent:
        lines.append("Some requirements checks need manual review. 🔎")
    else:
        lines.append("Some requirements checks failed. ❌")
    lines.append("")

    details_tag = "<details>" if all_pass else "<details open>"
    lines.append(details_tag)
    lines.append("<summary>Per-package results</summary>")
    lines.append("")

    header = "| Package | " + " | ".join(kind.value for kind in _KIND_ORDER) + " |"
    separator = "| --- | " + " | ".join("---" for _ in _KIND_ORDER) + " |"
    lines.append(header)
    lines.append(separator)
    for package in result.packages:
        cells = " | ".join(_cell(package, kind) for kind in _KIND_ORDER)
        lines.append(f"| {_version_label(package)} | {cells} |")
    lines.append("")

    for package in result.packages:
        lines.append(f"### {package.name}")
        for kind in _KIND_ORDER:
            lines.append(_detail_line(package, kind))
        lines.append("")

    lines.append("</details>")
    lines.append("")
    return "\n".join(lines)
